writing.exampleCode:
let mut v = vec![1, 2];
let a = &v[0];
let b = &v[1];   // two readers: fine
println!("{a} {b}");
v.push(3);       // writer, after the readers end

writing.practiceCode:
fn main() {
    let mut v = vec![1];
    let writer = &mut v;
    let reader = &v;
    println!("{writer:?} {reader:?}");
}
